const source = p => ({ doc_id: p.doc_id, titre: p.titre, repere: p.repere, page: p.page, version: p.version, ordre: p.ordre });
// Un refus cite la règle interne qui le fonde, quand un document en service la contient. La phrase citée est recopiée du document : elle est donc exacte.
const TERMES = { donnees_personnelles: ['tiers', 'mandat'], avis_medical: ['avis medical'] };
const regleDe = (motif, passages) => {
  const termes = TERMES[motif]; if (!termes) return null;
  const p = passages.find(x => termes.every(t => norm(x.contenu).indexOf(t) >= 0)); if (!p) return null;
  const phrase = (p.contenu.match(/[^.!?]+[.!?]+/g) || [p.contenu]).map(s => s.trim()).find(s => norm(s).indexOf(termes[0]) >= 0) || '';
  return phrase ? Object.assign(source(p), { extrait: phrase }) : null;
