const prep = $('Protéger la question').first().json, ctx = $('Chercher les passages proches').first().json;
const o = ($input.first().json || {}).output || {};
const cites = (Array.isArray(o.sources) ? o.sources : []).map(s => String(s).replace(/[\[\]\s]/g, '').toUpperCase());
const sources = ctx.passages.filter(p => cites.indexOf(p.cle) >= 0);
const extrait = String(o.extrait || '').trim();
const extraitOk = extrait.length >= 15 && sources.some(p => norm(p.contenu).indexOf(norm(extrait)) >= 0);
let statut = 'repondu', motif = String(o.motif_refus || 'aucun'), texte = '', note = '', regle = null;
if (!ctx.passages.length) { statut = 'non_trouve'; motif = 'base_vide'; }
else if (TEXTES[motif] && motif !== 'hors_documents') { statut = 'refuse'; regle = regleDe(motif, ctx.passages); }
else if (!o.trouve || motif === 'hors_documents') { statut = 'non_trouve'; motif = 'hors_documents'; }
else if (!sources.length || !extraitOk) { statut = 'bloque'; motif = 'source_non_verifiee'; }
if (statut === 'repondu') { texte = String(o.reponse || '').trim(); motif = ''; note = 'Réponse d\'une IA, à relire avant de la transmettre.'; }
else { texte = TEXTES[motif][0]; note = TEXTES[motif][1]; }
return [{ json: { statut: statut, motif: motif, libelle: LIBELLES[motif] || '', question: prep.question, origine: prep.origine, nb_masques: prep.nb_masques, types_masques: prep.types_masques,
  reponse: texte, note: note, extrait: statut === 'repondu' ? extrait : '', sources: statut === 'repondu' ? sources.map(source) : [], regle: regle,
  voisins: ctx.passages.map(p => ({ doc_id: p.doc_id, ordre: p.ordre, titre: p.titre, repere: p.repere, proximite: p.proximite })), nb_en_service: ctx.nb_en_service,
  etapes: [
